import 'package:ed25519_edwards/ed25519_edwards.dart' as ed;

void signAndVerify() {
  var keyPair = ed.generateKey();
  var message = Uint8List.fromList('test message'.codeUnits);
  var sig = ed.sign(keyPair.privateKey, message);
  var ok = ed.verify(keyPair.publicKey, message, sig);
  assert(ok);
}
